	}

	private void refreshSelectedModuleObjects() {
		selectedModuleObjects = provider.modulesPanel.getSelectedItems()
				.stream()
				.map(r => r.getValue().getValue())
				.collect(Collectors.toSet());
	}

	/* @Override */
